Translate("frFR", "azshara", {
	title = "Azshara",
	sections = {
		{
			title = "Résumé",
			text = [=[Azshara est une terre de bois rouges d'automne, de falaises brisées et de ruines englouties sur la côte nord-est de {link:kalimdor}Kalimdor{/link}, à l'est d'{link:ashenvale}Orneval{/link} et au sud de {link:winterspring}Berceau-de-l'Hiver{/link}. Elle porte le nom de la {link:queen-azshara}reine Azshara{/link}, et elle porte son souvenir comme une blessure. Des temples brisés penchent au-dessus de la {link:bay-of-storms}Baie des tempêtes{/link}, les colonnes de cités anciennes gisent à demi englouties dans le ressac, et les esprits des {link:high-elves}Bien-nés{/link} errent encore parmi les pierres. Peu de gens viennent ici de leur plein gré. Ceux qui viennent le font pour ce que cachent encore les ruines.]=],
		},
		{
			title = "Origines",
			text = [=[Aucune chronique ne donne l'année où les Bien-nés bâtirent pour la première fois sur ces rivages. Ce que l'on sait, c'est qu'à l'âge d'avant la {link:great-sundering}Fracture{/link}, c'était un pays de leurs cités et de leurs temples, et que ses plus grands mages y inscrivaient les lois des arcanes sur des tablettes et des runes, pour que tous les lisent. Quand le {link:well-of-eternity}puits d'Éternité{/link} fut détruit à la fin de la {link:war-of-the-ancients}guerre des Anciens{/link}, la terre fut déchirée. Une grande part de la cité d'{link:ruins-of-eldarath}Eldarath{/link} tomba dans la mer, et la côte devint la chose déchiquetée qu'elle est aujourd'hui. La reine et ses serviteurs furent perdus sous les flots. Les elfes de la nuit qui survécurent tournèrent le dos à ce lieu, et depuis dix mille ans ils l'évitent.]=],
		},
		{
			title = "De nos jours",
			text = [=[Azshara n'appartient à personne, et tout le monde en veut quelque chose. Les {link:naga}nagas{/link} Spitelash sont ressortis de la mer pour réclamer les ruines de leurs ancêtres. Des {link:satyrs}satyres{/link} {link:haldarr-encampment}Haldarr{/link} et Legashi hantent les bois. Une compagnie d'elfes de sang menée par la mage {link:magus-rimtori}Rimtori{/link} a dressé son camp sur les escarpements du nord pour fouiller à la recherche des trésors des Bien-nés. La {link:horde}Horde{/link} tient un petit avant-poste ensanglanté à {link:valormok}Valormok{/link}, et les {link:sentinels}Sentinelles{/link} veillent depuis la {link:talrendis-point}Halte de Talrendis{/link}, à la frontière d'{link:ashenvale}Orneval{/link}. Un archimage humain possède une tour dans les collines de l'ouest, un chasseur de démons vit sur une île de la baie, et un dragon bleu garde les bois du sud. Au nord, derrière une grande porte qu'aucun étranger n'a franchie, des furbolgs luttent contre une corruption qui monte des profondeurs.]=],
		},
		{
			title = "Habitants",
			text = [=[• {b}Les nagas Spitelash.{/b} Ils tiennent les {link:ruins-of-eldarath}Ruines d'Eldarath{/link}, les plages et les récifs, et leur seigneur de guerre règne depuis le {link:temple-of-zin-malor}Temple de Zin-Malor{/link}.
• {b}Les satyres.{/b} Le clan {link:haldarr-encampment}Haldarr{/link} rôde près de {link:valormok}Valormok{/link}, et les Legashi tiennent les bois du nord.
• {b}Les elfes de sang.{/b} Des arpenteurs et des récupérateurs servent la magus {link:magus-rimtori}Rimtori{/link}, qui chasse les reliques des Bien-nés.
• {b}Les furbolgs du nord.{/b} Ils gardent la porte de {link:blackmaw-hold}Blackmaw Hold{/link} et ne laissent aucun étranger en approcher.
• {b}Les géants des falaises.{/b} Ils parcourent les collines du sud et mangent la pierre même du pays.
• {b}Le Vol draconique bleu.{/b} {link:azuregos}Azuregos{/link} et les draconiens veillent sur l'antique magie de la côte.
• {b}Les makruras.{/b} Le peuple-crabe du {link:temple-of-arkkoran}Temple d'Arkkoran{/link} vénère son maître, le seigneur {link:lord-arkkoroc}Arkkoroc{/link}.
• {b}Les morts sans repos.{/b} Des apparitions bien-nées hantent les sanctuaires de l'ouest, liées aux arcanes qu'elles aimaient.]=],
		},
		{
			title = "Histoire",
			text = [=[• {b}L'âge des Bien-nés.{/b} {link:ruins-of-eldarath}Eldarath{/link} prospéra, et ses mages consacrèrent leur vie à l'étude des {link:arcane-magic}arcanes{/link}.
• {b}La {link:great-sundering}Fracture{/link}.{/b} Le Puits implosa, la terre se brisa, et la mer engloutit la moitié d'Eldarath.
• {b}Le long silence.{/b} Pendant dix mille ans, les ruines furent laissées aux esprits, aux bêtes et aux marées.
• {b}De nos jours.{/b} Les nagas sont revenus des profondeurs. Des chercheurs de trésors de toutes les races les ont suivis.]=],
		},
		{
			title = "Légendes de la côte",
			text = [=[• Les géants des falaises du sud dévorent la roche comme les ruines. Ce qui passe à travers eux durcit en azsharite, un cristal à la fois souple et très solide.
• Les elfes de sang appellent un gobelin qui a travaillé pour eux « {link:kim-jael}Kim'jael{/link} ». Il jure que cela veut dire « petit rat », et il ne leur a pas pardonné.
• Les tablettes d'{link:ruins-of-eldarath}Eldarath{/link} portent le nom de quatre sorciers bien-nés : Beth'{link:moon-priestess-amara}Amara{/link}, Jin'yael, Markri et Sael'hai.]=],
		},
	},
})

Translate("frFR", "talrendis-point", {
	title = "Halte de Talrendis",
	sections = {
		{
			title = "Résumé",
			text = [=[La Halte de Talrendis est l'avant-poste des {link:sentinels}Sentinelles{/link} à l'ouest d'{link:azshara}Azshara{/link}, près de la frontière d'{link:ashenvale}Orneval{/link}. Il est petit et vigilant. Un maître des hippogriffes garde ouverte par le ciel la seule route du retour, et l'arcière Brinna {link:valanaar}Valanaar{/link} répare les arcs des Sentinelles. Les Sentinelles surveillent ici la {link:horde}Horde{/link} à {link:valormok}Valormok{/link}, les satyres dans les collines et les esprits des sanctuaires de l'ouest. Un serviteur de la Terre-mère, {link:loh-atu}Loh'atu{/link}, campe parmi elles et a juré d'aider les elfes à purifier le pays des satyres comme des morts bien-nés.]=],
		},
	},
})

Translate("frFR", "valormok", {
	title = "Valormok",
	sections = {
		{
			title = "Résumé",
			text = [=[Valormok est le camp de la {link:horde}Horde{/link} dans l'ouest d'{link:azshara}Azshara{/link}, au nord du {link:haldarr-encampment}Campement des Haldarr{/link}. C'est un poste isolé, avec un maître des coursiers du vent, un forgeron et un cuisinier. Il comptait autrefois une douzaine de guerriers. La plupart suivirent l'elfe de sang {link:magus-rimtori}Rimtori{/link} dans les terres sauvages sur l'ordre de Belgrom Rockmaul, d'{link:orgrimmar}Orgrimmar{/link}, et elle les tua. {link:ag-tor-bloodfist}Ag'tor Bloodfist{/link}, qui est resté, veut se venger. {link:jediga}Jediga{/link}, envoyée ici en punition, veut faire des profits. Ni l'un ni l'autre n'attend d'aide d'Orgrimmar. Ses coursiers du vent sont la seule route rapide de la Horde pour quitter Azshara.]=],
		},
	},
})

Translate("frFR", "ruins-of-eldarath", {
	title = "Ruines d'Eldarath",
	aliases = { "Eldarath" },
	sections = {
		{
			title = "Résumé",
			text = [=[Eldarath était une cité des Bien-nés sur les falaises dominant la {link:bay-of-storms}Baie des tempêtes{/link}. Quand le monde se brisa, une grande part en tomba dans la mer. Ce qui se dresse aujourd'hui est un dédale de pierre pâle et d'arches brisées, tenu par les nagas Spitelash. Quatre grandes tablettes se dressent encore parmi les ruines, chacune au nom d'un sorcier bien-né, et des érudits d'{link:ironforge}Ironforge{/link} jusqu'à l'{link:undercity}Undercity{/link} en veulent des copies. Les mares de son rivage sont souillées. Un {link:tauren}tauren{/link} qui but à l'une d'elles tomba malade, et les apothicaires réprouvés prirent un intérêt malsain à cette eau.]=],
		},
	},
})

Translate("frFR", "temple-of-zin-malor", {
	title = "Temple de Zin-Malor",
	aliases = { "Zin-Malor" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le Temple de Zin-Malor se dresse au cœur des {link:ruins-of-eldarath}Ruines d'Eldarath{/link}. Il abritait autrefois un cristal capable de contenir et de commander de grandes forces arcaniques. Ceux qui le volèrent avaient de mauvais desseins, et le cristal se brisa. Ses gardiens devinrent des esprits maudits, et les écrits sacrés des Bien-nés furent laissés à pourrir dans les salles du temple. Aujourd'hui, le seigneur de guerre {link:naga}naga{/link} {link:warlord-krellian}Krellian{/link} tient le temple comme son siège, derrière un mur de gardes, et rassemble toute la magie qu'il peut trouver. Les nagas le gardent plus farouchement que toute autre partie des ruines.]=],
		},
	},
})

Translate("frFR", "bay-of-storms", {
	title = "Baie des tempêtes",
	sections = {
		{
			title = "Résumé",
			text = [=[La Baie des tempêtes est un large golfe gris qui mord au milieu d'{link:azshara}Azshara{/link}. Ses eaux sont agitées, et ses îles sont rares. Sur sa rive nord se trouve le Frai d'{link:hetaera}Hetaera{/link}, l'antre d'une bête à trois têtes qui se dit souveraine de ces mers. Les makruras d'{link:temple-of-arkkoran}Arkkoran{/link} chassent dans ses eaux orientales, et les nagas nagent sous tout cela. Sur une petite île au sud, gardée par trois gangrechiens, vit le chasseur de démons {link:loramus-thalipedes}Loramus Thalipedes{/link}.]=],
		},
	},
})

Translate("frFR", "temple-of-arkkoran", {
	title = "Temple d'Arkkoran",
	aliases = { "Arkkoran" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le Temple d'Arkkoran se dresse au bord de l'eau, à l'est d'{link:azshara}Azshara{/link}. C'est la demeure des makruras, le peuple-crabe de la côte, et de l'être immense qu'ils servent : le seigneur {link:lord-arkkoroc}Arkkoroc{/link}, que même le chasseur de démons {link:loramus-thalipedes}Loramus{/link} appelle un dieu mineur. Ses oracles, ses claqueurs et ses pinceurs gardent les abords et attaquent tout étranger qu'ils trouvent. Ceux qui l'atteignent vivants peuvent marchander avec lui, mais il fixe toujours un prix, et le dernier prix qu'il a demandé fut payé dans le sang.]=],
		},
	},
})

Translate("frFR", "thalassian-base-camp", {
	title = "Camp de base thalassien",
	sections = {
		{
			title = "Résumé",
			text = [=[Sur les escarpements de la péninsule du nord, une compagnie d'elfes de sang a établi son camp. Ses arpenteurs et ses récupérateurs ratissent le pays à la recherche des trésors perdus des Bien-nés, et ils broient la magie qu'ils trouvent en une poussière scintillante. Leur chef est la magus {link:magus-rimtori}Rimtori{/link}. Elle engagea des orcs et un gobelin pour l'aider, et elle se retourna contre les uns et l'autre. Près de ses propres tentes se dresse un cercle de cristaux arcaniques, disposé selon le modèle d'un ancien livre d'invocation.]=],
		},
	},
})

Translate("frFR", "legashi-encampment", {
	title = "Campement Legashi",
	aliases = { "Campement Legash", "Legashi Stronghold" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les satyres Legashi tiennent les bois du nord d'{link:azshara}Azshara{/link}, à l'est d'Ursolan et au nord du camp des elfes de sang. Leurs invocateurs infernaux et leurs voleurs servent le maître Feardred. Sur une colline au-dessus d'eux, un gobelin têtu nommé {link:kim-jael}Kim'jael{/link} tient son propre camp et ne semble pas les craindre. De tous les satyres d'Azshara, les Legashi sont les plus nombreux. Les voyageurs disent qu'une de leurs places fortes s'est récemment élevée tout près, mais nul ne sait ce qu'elle abrite.]=],
		},
	},
})

Translate("frFR", "haldarr-encampment", {
	title = "Campement des Haldarr",
	aliases = { "Haldarr" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le Campement des Haldarr se trouve au sud-ouest d'{link:azshara}Azshara{/link}, près du camp de la {link:horde}Horde{/link} à {link:valormok}Valormok{/link}. C'est le repaire du clan Haldarr des {link:satyrs}satyres{/link} : des filous, des gangrejurés et des brutes qui furent autrefois des elfes. Ils souillent les bois que foulait jadis {link:cenarius}Cenarius{/link}. {link:loh-atu}Loh'atu{/link}, de la {link:talrendis-point}Halte de Talrendis{/link}, a juré à la Terre-mère d'aider à les chasser, et il paie ceux qui reviennent vivants de leur camp.]=],
		},
	},
})

Translate("frFR", "shadowsong-shrine", {
	title = "Sanctuaire de Shadowsong",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Sanctuaire de Shadowsong est une ruine à l'ouest d'{link:azshara}Azshara{/link}, au nord-est de la {link:talrendis-point}Halte de Talrendis{/link}. Il est hanté. Des apparitions et des petites liches bien-nées dérivent parmi ses pierres, toujours avides de la magie arcanique qui les a perdues. Les esprits tourmentent tous les peuples sans distinction, et l'on dit qu'une faim comme la leur attire l'œil de la {link:burning-legion}Légion ardente{/link}. Les {link:sentinels}Sentinelles{/link} ont demandé qu'ils soient libérés de ce monde. Non loin erre un fantôme plus sombre, qui porte le nom du capitaine de la reine Azshara.]=],
		},
	},
})

Translate("frFR", "ravencrest-monument", {
	title = "Colosse de Ravencrest",
	sections = {
		{
			title = "Résumé",
			text = [=[Sur les falaises de la pointe sud d'{link:azshara}Azshara{/link}, au-dessus de la haute mer, gisent les restes d'une statue colossale des anciens elfes. Seules ses jambes sont encore debout. Le reste gît brisé autour d'elles, ou est tombé dans les vagues. Elle porte le nom de la maison de Ravencrest, mais aucune chronique ne dit qui elle honorait ni quand elle fut élevée. Les nagas Spitelash errent aujourd'hui parmi les débris. On ne peut l'atteindre que par la terre, par un pont.]=],
		},
	},
})

Translate("frFR", "southridge-beach", {
	title = "Plage des Crêtes du sud",
	sections = {
		{
			title = "Résumé",
			text = [=[La Plage des Crêtes du sud s'étend sur la côte sud d'{link:azshara}Azshara{/link}, sous les forêts où le dragon bleu {link:azuregos}Azuregos{/link} monte la garde. C'est ici que le navire {i}Horizon Scout{/i} vint chercher un mouillage sûr, sous le commandement du capitaine {link:captain-vanessa-beltis}Vanessa Beltis{/link}. Le soleil n'était pas couché depuis une heure quand les nagas tombèrent sur son équipage. Les survivants se retranchèrent dans une vallée au-dessus de la plage, et ils y attendent encore, sachant que les nagas reviendront. Certains de ses passagers étaient venus à Azshara pour leurs propres affaires.]=],
		},
	},
})

Translate("frFR", "blackmaw-hold", {
	title = "Blackmaw Hold",
	sections = {
		{
			title = "Résumé",
			text = [=[Au nord d'{link:azshara}Azshara{/link} se dresse une grande porte des furbolgs. Aussi loin que remontent les souvenirs de {link:kalimdor}Kalimdor{/link}, elle est restée fermée, et ses gardes ont chassé tout étranger qui s'en approchait. Derrière elle se trouve Blackmaw Hold, une vaste cité {link:furbolgs}furbolg{/link} taillée profondément dans la montagne. Son peuple combat une corruption qui a commencé à remuer dans ses profondeurs. On dit que ses tunnels descendent plus loin encore, vers des lieux plus anciens que la cité elle-même.]=],
		},
	},
})

Translate("frFR", "loramus-thalipedes", {
	title = "Loramus Thalipedes",
	subtitle = "Le chasseur de démons d'Azshara",
	found = "Une petite île au sud de la Baie des tempêtes",
	hint = [=[Fouillez les îles de la Baie des tempêtes pour trouver celui qui chasse les démons.]=],
	allegiance = "Aucune, hormis sa propre chasse",
	aliases = { "Loramus" },
	sections = {
		{
			title = "Résumé",
			text = [=[Loramus Thalipedes est un chasseur de démons qui vit seul sur une île de la {link:bay-of-storms}Baie des tempêtes{/link}. Trois gangrechiens le gardent : Raytaf, Shahiar et Zaman. Il n'a aucune patience pour les interruptions. Pourtant, il en sait plus sur les seigneurs de la {link:burning-legion}Légion ardente{/link} en ce monde que n'importe quel sage des royaumes, et il aidera quiconque est assez fou pour les chasser.]=],
		},
		{
			title = "Importance",
			text = [=[Loramus est le seul à savoir comment blesser {link:razelikh-the-defiler}Razelikh{/link} le Profanateur. Il connaît l'histoire de la retraite du seigneur {link:lord-kazzak}Kazzak{/link} dans la {link:the-tainted-scar}Balafre impure{/link}, le pacte qui lie les trois capitaines de Razelikh, et le rite par lequel on peut apprendre le vrai nom du Profanateur. Sans lui, la guerre contre le seigneur démon des {link:blasted-lands}Terres foudroyées{/link} n'aurait pas pu être menée du tout.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il accomplit un rituel d'illumination pour apprendre comment briser la protection de {link:razelikh-the-defiler}Razelikh{/link}.
• Il envoie des chercheurs auprès du seigneur {link:lord-arkkoroc}Arkkoroc{/link} pour acheter le vrai nom du démon.
• Il prépare de l'azsharite trempée pour le forgeron {link:galvan-the-ancient}Galvan l'Ancien{/link}, le seul qui puisse la forger.]=],
		},
		{
			title = "Non consigné",
			text = [=[Aucune chronique ne dit qui était Loramus avant de commencer sa chasse, depuis combien de temps il vit sur son île, ni comment il en vint à connaître {link:galvan-the-ancient}Galvan{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Le récit du Profanateur",
			hint = "Asseyez-vous et écoutez le récit du chasseur de démons.",
			text = [=[Ceux qu'envoie le {link:fallen-hero-of-the-horde}Héros déchu de la Horde{/link} trouvent Loramus peu accueillant. Il raconte son histoire malgré tout, et il n'aime pas être interrompu. Quand la Légion fut vaincue, {link:lord-kazzak}Kazzak{/link} fut repoussé dans la {link:the-tainted-scar}Balafre impure{/link}, et {link:razelikh-the-defiler}Razelikh{/link}, le plus redouté de ses lieutenants, fut envoyé tenir le pays pour lui. Les ogres et les cultistes se rangèrent à ses côtés, de même que les trois qui gardent aujourd'hui son amulette.]=],
		},
		{
			title = "Le nom de la bête",
			hint = [=[Apprenez le vrai nom du démon auprès du seigneur des makruras.]=],
			text = [=[Seule une arme qui porte le vrai nom d'un démon peut le blesser, lui et tous ceux qui le servent. Loramus ne pouvait apprendre ce nom lui-même. Il envoya son aide au {link:temple-of-arkkoran}Temple d'Arkkoran{/link}, et le prix du seigneur des makruras fut le sang. Le nom revint avec une trempe tirée des têtes d'une bête : {link:razelikh-the-defiler}Rakh'likh{/link}.]=],
		},
		{
			title = "Felbane",
			hint = [=[Portez l'envoi du chasseur de démons au forgeron de l'ordre du Mithril.]=],
			text = [=[Avec l'azsharite des collines du sud et la trempe d'{link:lord-arkkoroc}Arkkoroc{/link}, les matériaux étaient prêts. Loramus les envoya au sud, à {link:galvan-the-ancient}Galvan l'Ancien{/link}, dans la {link:stranglethorn-vale}Vallée de Strangleronce{/link}. Le vieux forgeron n'avait pas entendu le nom du chasseur de démons depuis bien des années.]=],
		},
	},
	mentions = {
		{ text = "Le chasseur de démons" },
		{ text = "Loramus" },
		{ text = "Briser la protection" },
		{ text = "Le nom de la bête" },
		{ text = "Azsharite" },
		{ text = "La forge de Felbane" },
	},
	bonds = {
		{ id = "razelikh-the-defiler", name = "Razelikh le Profanateur", note = "le démon qu'il chasse" },
		{ id = "lord-kazzak", name = "Seigneur Kazzak", note = "le maître du Profanateur" },
		{ id = "lord-arkkoroc", name = "Seigneur Arkkoroc", note = "connaît le vrai nom" },
		{ id = "galvan-the-ancient", name = "Galvan l'Ancien", note = "une vieille connaissance" },
		{ id = "fallen-hero-of-the-horde", name = "Héros déchu de la Horde", note = "lui envoie des chasseurs" },
	},
})

Translate("frFR", "archmage-xylem", {
	title = "Archimage Xylem",
	subtitle = "Maître de la tour des collines",
	found = "Sa tour sur les falaises dominant l'ouest d'Azshara",
	hint = [=[Trouvez l'archimage dont la tour domine Azshara. Son serviteur attend en contrebas.]=],
	allegiance = "Ses propres études",
	aliases = { "Xylem" },
	sections = {
		{
			title = "Résumé",
			text = [=[L'archimage Xylem est un mage humain qui a élu domicile dans une tour haut perchée dans les collines d'{link:azshara}Azshara{/link}. Les visiteurs doivent d'abord trouver son serviteur {link:sanath-lim-yo}Sanath Lim-yo{/link}, qui les envoie à la tour par magie. Xylem est fier, froid et très puissant. Il est humain, comme le dit {link:jediga}Jediga{/link} de {link:valormok}Valormok{/link}, mais il n'agit comme aucun humain qu'elle ait jamais rencontré.]=],
		},
		{
			title = "Importance",
