	aliases = { "Hydraxis" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le duc Hydraxis est un seigneur élémentaire de l'eau qui demeure sur une île au large de la côte est d'{link:azshara}Azshara{/link}. Il commande les Hydraxiens. Il porte en lui un aspect de Neptulon, le grand seigneur des marées, et il mène une vieille guerre contre les autres {link:elements}éléments{/link} : l'air, la terre et surtout le feu.]=],
		},
