			title = "Importance",
			text = [=[Hydraxis est l'une des rares puissances élémentaires qui traitent avec les mortels. Il le fait pour sa guerre. Il ne se soucie ni de l'{link:alliance}Alliance{/link} ni de la {link:horde}Horde{/link}, seulement de la pureté de l'eau et de la défaite du feu. Chez les mortels prêts à se battre, il voit la chance d'une véritable alliance.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il cherche à guérir les élémentaires d'eau que la peste de {link:lordaeron}Lordaeron{/link} a pervertis.
• Il envoie ses alliés contre les serviteurs de l'air et de la terre dans {link:stranglethorn-vale}la Vallée{/link} des cristaux, en {link:silithus}Silithus{/link}.
• Il cherche la défaite des serviteurs du feu qui tiennent le {link:blackrock-mountain}Mont Blackrock{/link}.]=],
		},
		{
			title = "Non consigné",
			text = [=[Aucune chronique des mortels ne dit depuis combien de temps Hydraxis garde son île, ni pourquoi les Hydraxiens ont choisi {link:azshara}Azshara{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Eau empoisonnée",
			hint = "Aidez les Hydraxiens à rétablir leurs semblables souillés.",
			text = [=[Une troupe d'élémentaires d'eau partit dans les {link:eastern-plaguelands}Maleterres de l'est{/link} et en revint malade. Pour les Hydraxiens, c'était un outrage. Hydraxis donna une fiole de l'essence même de Neptulon pour les guérir. Le remède ne put apaiser la folie qui suivit.]=],
		},
		{
			title = "L'œil de l'Emberseer",
			hint = "Prouvez votre force contre un serviteur du feu captif.",
			text = [=[Tout en haut du Pic {link:blackrock-mountain}Blackrock{/link}, les orcs avaient enchaîné un serviteur du feu. Hydraxis voulait son œil. Quand il le reçut, il jugea que son nouvel allié avait de la ruse autant que de la force, et il commença à parler du Cœur du Magma.]=],
		},
